{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "In healthy human male volunteers, absolute oral bioavailability was 96% (range 92-102%) for a 10 mg oral solution compared with iv infusion, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In humans, absolute oral bioavailability after oral ingestion was reported as 73 ± 25%, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In healthy male volunteers, absolute oral bioavailability was 44.3 ± 8.6% for a 30 mg oral solution versus IV, the lowest retrieved quantitative value but still well above 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved quantitative human oral bioavailability records exceed 20%, with values from about 44% to 96%; therefore the F >= 20% threshold is supported.",
  "evidence_gaps": [
    "Some records are qualitative or use an unspecified bioavailability type, but the strongest numeric absolute measurements consistently support high bioavailability.",
    "No retrieved evidence supports F < 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

